const body = $json;
const text = (body.text || body.body || '').trim();

return [{
  json: {
    messageId: body.messageId || body.id || '',
    from: body.from || body.userId || '',
    type: body.type || 'text',
    text,
    mediaPath: body.mediaPath || '',
    languageHint: body.languageHint || '',
    timestamp: body.timestamp || Date.now()
  }
}];

const incoming = $items('Normalize Input')[0].json;
const sessionResult = $input.first().json;
const session = sessionResult.found ? sessionResult.session : { userId: incoming.from, step: 0, state: {} };

let step = session.step ?? 0;
let state = session.state ?? {};
let replyText = '';
const text = (incoming.text || '').trim();

if (incoming.type === 'voice') {
  replyText = 'Thanks for the voice note. I’m processing it now.';
}

if (step === 0) {
  replyText = 'Hi! Welcome to onboarding. What is your full name?';
  step = 1;
} else if (step === 1) {
  state.fullName = text;
  replyText = 'Thanks. Which language would you like to continue in?';
  step = 2;
} else if (step === 2) {
  state.language = text;
  replyText = 'Great. Please share your email address.';
  step = 3;
} else if (step === 3) {
  state.email = text;
  replyText = 'What service are you interested in?';
  step = 4;
} else if (step === 4) {
  state.service = text;
  replyText = 'Thanks — your onboarding is complete.';
  step = 5;
} else {
  replyText = 'You are already onboarded. Reply HELP for support.';
}

return [{
  json: {
    ...incoming,
    session: { userId: incoming.from, step, state },
    replyText
  }
}];
